import{_ as t,o,c as s,a3 as a}from"./chunks/framework.B02wg2PO.js";const g=JSON.parse('{"title":"Backups & Upgrades","description":"","frontmatter":{},"headers":[],"relativePath":"operations/backup-and-upgrades.md","filePath":"operations/backup-and-upgrades.md"}'),i={name:"operations/backup-and-upgrades.md"};function d(r,e,n,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="backups-upgrades" tabindex="-1">Backups &amp; Upgrades <a class="header-anchor" href="#backups-upgrades" aria-label="Permalink to &quot;Backups &amp; Upgrades&quot;">​</a></h1><p>Saidi keeps state in two places: MongoDB, which is the source of truth for every structured record, and a data directory on disk, which holds binary artifacts and a materialized working copy of your memory files. A backup that covers only one of them is not a backup. This page lists exactly what to copy, how versioning works, which migrations the code runs for you, and how to upgrade without losing anything.</p><h2 id="what-is-durable-and-where" tabindex="-1">What is durable, and where <a class="header-anchor" href="#what-is-durable-and-where" aria-label="Permalink to &quot;What is durable, and where&quot;">​</a></h2><h3 id="mongodb-—-the-source-of-truth" tabindex="-1">MongoDB — the source of truth <a class="header-anchor" href="#mongodb-—-the-source-of-truth" aria-label="Permalink to &quot;MongoDB — the source of truth&quot;">​</a></h3><p><code>src/db/mongo.ts</code> treats MongoDB as required: on disconnect the process terminates rather than accept non-durable changes, and there is deliberately no degraded file-backed mode. The database name is chosen by the mode flag, not by your connection string — <code>src/db/mongo-uri.ts</code> forces the database path to <code>saidi</code> in local mode and <code>saidi_cloud</code> when <code>SAIDI_CLOUD=1</code>, preserving your host, credentials, and query options.</p><p>The models under <code>src/db/models/</code> define what lives there:</p><table tabindex="0"><thead><tr><th>Collection area</th><th>Model file</th><th>Holds</th></tr></thead><tbody><tr><td>Runs</td><td><code>run.model.ts</code></td><td>The full run record, thread, and usage log</td></tr><tr><td>Chats</td><td><code>chat.model.ts</code></td><td>Main-chat conversations</td></tr><tr><td>Crons / Reflexes</td><td><code>cron.model.ts</code>, <code>reflex.model.ts</code></td><td>Schedules and event rules</td></tr><tr><td>Playbooks</td><td><code>playbook.model.ts</code></td><td>Saved run playbooks</td></tr><tr><td>Activity</td><td><code>activity.model.ts</code></td><td>The activity stream</td></tr><tr><td>Credits</td><td><code>credit.model.ts</code></td><td>Wallet + ledger</td></tr><tr><td>Memory</td><td><code>memory.model.ts</code></td><td>Markdown memory documents</td></tr><tr><td>Agent definitions</td><td><code>agent-def.model.ts</code></td><td>Packed custom-agent definitions</td></tr><tr><td>Settings</td><td><code>settings.model.ts</code></td><td>System settings incl. host/port</td></tr><tr><td>Secrets</td><td><code>secrets.model.ts</code></td><td>Credentials, envelope-encrypted under <code>SAIDI_MASTER_KEY</code></td></tr><tr><td>Providers / scan roots</td><td><code>provider-profiles.model.ts</code>, <code>scan-roots.model.ts</code></td><td>Model routing, project scan roots</td></tr><tr><td>Channels</td><td><code>channel-config.model.ts</code>, <code>channel-identity.model.ts</code></td><td>Telegram and other adapters</td></tr><tr><td>Auth / orgs</td><td><code>auth.model.ts</code>, <code>org.model.ts</code></td><td>Users, orgs, memberships (cloud)</td></tr><tr><td>Migrations</td><td><code>migration.model.ts</code></td><td>Completion markers for one-time migrations</td></tr><tr><td>Runtime state</td><td><code>runtime-state.model.ts</code></td><td>Process-level state</td></tr></tbody></table><h3 id="the-data-directory-—-artifacts-and-working-copies" tabindex="-1">The data directory — artifacts and working copies <a class="header-anchor" href="#the-data-directory-—-artifacts-and-working-copies" aria-label="Permalink to &quot;The data directory — artifacts and working copies&quot;">​</a></h3><p><code>resolveDataDir()</code> in <code>src/orchestrator/config.ts</code> picks <code>DATA_DIR</code> in this order: <code>SAIDI_HOME</code> → the repo root when <code>SAIDI_DEV</code> is set → <code>~/.saidi</code>. In cloud mode every org&#39;s state nests one level down under <code>DATA_DIR/orgs/&lt;orgId&gt;/</code> (<code>src/orchestrator/tenant/paths.ts</code>).</p><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th><th>Reconstructible?</th></tr></thead><tbody><tr><td><code>DATA_DIR/config/settings.json</code></td><td>Bind host/port read by the CLI launcher before the server boots</td><td>Yes — Mongo settings win at runtime</td></tr><tr><td><code>DATA_DIR/config/update-state.json</code></td><td>Auto-update attempt marker</td><td>Yes</td></tr><tr><td><code>DATA_DIR/memory/global.md</code></td><td>Personal global memory</td><td>Mirrored in Mongo</td></tr><tr><td><code>DATA_DIR/memory/members/&lt;userId&gt;/global.md</code></td><td>Per-member personal memory (cloud)</td><td>Mirrored in Mongo</td></tr><tr><td><code>DATA_DIR/memory/projects/*.md</code></td><td>Per-project memory</td><td>Mirrored in Mongo</td></tr><tr><td><code>DATA_DIR/memory/agents/*.md</code></td><td>Per-agent memory</td><td>Mirrored in Mongo</td></tr><tr><td><code>DATA_DIR/memory/learning.json</code></td><td>Learned preferences</td><td>Mirrored in Mongo</td></tr><tr><td><code>DATA_DIR/memory/runs/&lt;id&gt;/assets/</code></td><td>Run images and deliverables, served as binaries</td><td><strong>No</strong></td></tr><tr><td><code>DATA_DIR/memory/runs/&lt;id&gt;/work/&lt;agent&gt;/</code></td><td>Per-agent run workspace</td><td><strong>No</strong></td></tr><tr><td><code>DATA_DIR/memory/runs/&lt;id&gt;/repos/&lt;project&gt;/</code></td><td>Per-run git worktrees</td><td>Regenerable from the repo</td></tr><tr><td><code>DATA_DIR/memory/runs/&lt;id&gt;/output/</code>, <code>shared/</code></td><td>Sandbox drop zone and handoff notes</td><td><strong>No</strong></td></tr><tr><td><code>DATA_DIR/memory/runs/&lt;id&gt;/agent-config/</code></td><td>Per-run SDK session state (<code>CLAUDE_CONFIG_DIR</code>)</td><td><strong>No</strong></td></tr><tr><td><code>DATA_DIR/agents/</code></td><td>Custom agent homes: <code>AGENT.md</code> folders, skills, <code>mcp.json</code></td><td>Packed into Mongo by the migration, but treat as primary</td></tr><tr><td><code>DATA_DIR/orgs/&lt;orgId&gt;/…</code></td><td>The same layout, per org (cloud only)</td><td>—</td></tr><tr><td><code>DATA_DIR/repos/</code></td><td>Server-side project clones (cloud)</td><td>Regenerable from origin</td></tr></tbody></table><p>Two rules from the source make this concrete:</p><ul><li><code>src/orchestrator/runs/persistence.ts</code>: &quot;Run image assets stay on disk (<code>&lt;runsRoot&gt;/&lt;id&gt;/assets/</code>, served binary); only the JSON run record moves to MongoDB.&quot;</li><li><code>src/memory/mongo.ts</code>: &quot;Mongo is the source of truth; the on-disk files under the org&#39;s memory dir are a materialized working copy.&quot; <code>initOrgMemory()</code> deletes disk files that no longer exist in Mongo, so the disk copy is not authoritative for memory.</li></ul><p><code>src/orchestrator/legacy-mongo-migration.ts</code> states the same boundary from the other side: &quot;Binary assets, agent workspaces and provider session files are intentionally not database records and remain on disk.&quot;</p><h2 id="what-to-back-up" tabindex="-1">What to back up <a class="header-anchor" href="#what-to-back-up" aria-label="Permalink to &quot;What to back up&quot;">​</a></h2><p>Back up <strong>both</strong> of these, from the same point in time:</p><ol><li><strong>The MongoDB database</strong> — <code>saidi</code>, or <code>saidi_cloud</code> in cloud mode.</li><li><strong>The whole data directory</strong> — <code>$SAIDI_HOME</code>, or <code>~/.saidi</code> if you never set it. In the shipped Docker setup this is the <code>saidi-data</code> volume mounted at <code>/data</code>.</li></ol><p>Plus, separately from the automated backup:</p><ol start="3"><li><strong><code>MONGODB_URI</code></strong> — it is the one credential that cannot live in Mongo, so it is not inside either backup.</li><li><strong><code>SAIDI_MASTER_KEY</code></strong>, if set. Secrets and provider profiles are envelope-encrypted at rest under it. A database backup without this key is undecryptable.</li></ol><p>A minimal procedure:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Stop the server so debounced writes are drained (SIGTERM triggers the</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    graceful shutdown in src/orchestrator/server.ts).</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -TERM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIDI_PID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Dump the database.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mongodump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --uri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MONGODB_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saidi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backup/mongo-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Archive the data directory.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -czf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backup/saidi-home-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dirname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIDI_HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;)&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">basename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIDI_HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;)&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Stop the server first if you can</p><p><code>gracefulShutdown()</code> in <code>src/orchestrator/server.ts</code> explicitly drains the 400 ms-debounced activity writes and flushes pending run writes <em>before</em> disconnecting Mongo. A snapshot taken while the process is live can miss the last message of a turn, or reload a finishing run as <code>paused</code>.</p></div><p>Run workspaces under <code>memory/runs/&lt;id&gt;/work/</code> and <code>repos/</code> can be large. They are the evidence trail for a run — see <a href="/docs/concepts/runs">Runs</a>. If you exclude them to save space, do it deliberately and know that run assets under <code>assets/</code> are <strong>not</strong> reconstructible from the database.</p><h2 id="how-versioning-works" tabindex="-1">How versioning works <a class="header-anchor" href="#how-versioning-works" aria-label="Permalink to &quot;How versioning works&quot;">​</a></h2><ul><li>The root <code>package.json</code> <code>version</code> field is the single source of truth. As of this writing it is <code>1.19.0</code>.</li><li><code>src/version.ts</code> imports it directly (<code>import pkg from &quot;../package.json&quot;</code>), so <code>APP_VERSION</code> and the tagged release can never drift.</li><li><code>scripts/sync-version.mjs</code> mirrors the root version into <code>client/package.json</code> so the client bundle and the server report the same version. It runs automatically from the npm <code>version</code> lifecycle hook: <code>node scripts/sync-version.mjs &amp;&amp; git add client/package.json CHANGELOG.md</code>.</li><li><code>CHANGELOG.md</code> follows Keep a Changelog, and Saidi follows Semantic Versioning. Releases are generated by release-please from Conventional Commits: <code>fix:</code> → patch, <code>feat:</code> → minor, <code>feat!:</code> or <code>BREAKING CHANGE:</code> → major.</li><li><code>RELEASES[0]</code> in <code>src/version.ts</code> carries a fallback release note, stamped by release-please via the <code>x-release-please-version</code> anchor; the in-app &quot;What&#39;s New&quot; dialog normally shows the fetched GitHub release body instead.</li></ul><h3 id="how-updates-are-detected-and-installed" tabindex="-1">How updates are detected and installed <a class="header-anchor" href="#how-updates-are-detected-and-installed" aria-label="Permalink to &quot;How updates are detected and installed&quot;">​</a></h3><p><code>src/orchestrator/update-check.ts</code> polls the public distribution repo&#39;s <code>releases/latest</code> on boot and every 6 hours. Two optional overrides exist: <code>SAIDI_UPDATE_MANIFEST_URL</code> (a JSON manifest, highest priority) and <code>SAIDI_GITHUB_TOKEN</code> (read the private source repo&#39;s release instead).</p><p><code>src/orchestrator/auto-update.ts</code> acts on that detection only when <strong>all</strong> of these hold: <code>settings.autoUpdate</code> is on (default on), local mode, running under the supervisor, running a published <code>dist</code> install, and the target version is not recorded as known-bad in <code>config/update-state.json</code>. When they do, it waits for the orchestrator to go idle and exits with <code>UPDATE_EXIT_CODE</code> (76). The supervisor then runs <code>npm i -g github:saeed9321/saidi-agent</code> <em>between</em> spawns — the install cannot happen in-process because it rewrites the package directory the server is executing from — and relaunches. If the new child dies within 60 seconds, the supervisor reinstalls the previous version. See <a href="/docs/operations/deployment">Deployment &amp; Self-Hosting</a> for the supervisor&#39;s exit-code table.</p><p>This is why persistent state must live outside the package: <code>npm i -g</code> replaces the package directory on every update.</p><h2 id="migrations-the-code-actually-runs" tabindex="-1">Migrations the code actually runs <a class="header-anchor" href="#migrations-the-code-actually-runs" aria-label="Permalink to &quot;Migrations the code actually runs&quot;">​</a></h2><p>All of these are automatic and idempotent unless noted.</p><h3 id="_1-legacy-in-package-state-→-data-dir" tabindex="-1">1. Legacy in-package state → <code>DATA_DIR</code> <a class="header-anchor" href="#_1-legacy-in-package-state-→-data-dir" aria-label="Permalink to &quot;1. Legacy in-package state → \`DATA_DIR\`&quot;">​</a></h3><p><code>migrateLegacyDataDir()</code> in <code>src/orchestrator/data-migrate.ts</code> runs first thing in <code>main()</code>, before anything reads state. Older builds wrote <code>memory/</code>, <code>config/</code>, and <code>agents/</code> relative to the install directory; this copies them into <code>DATA_DIR</code> — but <strong>only when <code>DATA_DIR</code> holds none of those groups yet</strong>, so it can never clobber existing data. It is best-effort and never throws.</p><h3 id="_2-saidi-home-structured-records-→-mongodb" tabindex="-1">2. <code>SAIDI_HOME</code> structured records → MongoDB <a class="header-anchor" href="#_2-saidi-home-structured-records-→-mongodb" aria-label="Permalink to &quot;2. \`SAIDI_HOME\` structured records → MongoDB&quot;">​</a></h3><p><code>migrateSaidiHomeToMongo()</code> in <code>src/orchestrator/legacy-mongo-migration.ts</code> runs immediately after the Mongo connection succeeds. It imports runs, chats, crons, reflexes, playbooks, the credit wallet and ledger, activity, channel configs and identities, channel sessions, Telegram accounts, memory documents, and packed agent definitions — plus the platform config (settings, secrets, provider profiles, scan roots).</p><p>The safety properties are explicit in the source:</p><ul><li>The completion marker (<code>saidi-home-structured-v1</code>, in the migrations collection) is written <strong>only after</strong> every discovered record reads back from Mongo, and after the platform config docs are verified to exist.</li><li>Import operations are idempotent, so a crash before the marker simply retries the incomplete migration on the next boot.</li><li>Invalid legacy JSON <strong>aborts discovery</strong> rather than silently setting the marker — there is a test for exactly that (<code>src/orchestrator/legacy-mongo-migration.test.ts</code>).</li><li>Binary assets, agent workspaces, and provider session files are intentionally left on disk.</li></ul><h3 id="_3-memory-disk-→-mongo-then-mongo-→-disk" tabindex="-1">3. Memory disk → Mongo, then Mongo → disk <a class="header-anchor" href="#_3-memory-disk-→-mongo-then-mongo-→-disk" aria-label="Permalink to &quot;3. Memory disk → Mongo, then Mongo → disk&quot;">​</a></h3><p><code>initOrgMemory(orgId)</code> in <code>src/memory/mongo.ts</code> runs on org hydration. When Mongo holds no memory docs for the org it performs a one-time disk → Mongo import; thereafter it materializes Mongo docs to files and deletes stale ones. It throws if Mongo is unavailable.</p><h3 id="_4-provider-selection-backfills" tabindex="-1">4. Provider selection backfills <a class="header-anchor" href="#_4-provider-selection-backfills" aria-label="Permalink to &quot;4. Provider selection backfills&quot;">​</a></h3><p><code>migrateModelProvider()</code> and <code>migrateRemovedNativeProvider()</code> (<code>src/orchestrator/data-migrate.ts</code>) seed the master model-provider selection for installs that predate it. They run before env hydration, because hydration enforces that selection onto the Anthropic environment variables.</p><h3 id="_5-single-user-→-cloud-manual-one-time" tabindex="-1">5. Single-user → cloud (manual, one-time) <a class="header-anchor" href="#_5-single-user-→-cloud-manual-one-time" aria-label="Permalink to &quot;5. Single-user → cloud (manual, one-time)&quot;">​</a></h3><p><code>scripts/migrate-to-cloud.mjs</code> is the only migration you invoke yourself. It turns an existing single-user data set into organization #1 of a <code>SAIDI_CLOUD=1</code> deployment:</p><ol><li>Creates the superadmin user (scrypt hash, email pre-verified), the organization, and the owner membership.</li><li>Backfills <code>orgId</code> (and <code>createdBy</code> where a human owns the record) onto <code>runs</code>, <code>crons</code>, <code>reflexes</code>, <code>activityevents</code>, and <code>creditledgers</code>.</li><li>Re-keys the credit wallet document from <code>default</code> to the new <code>orgId</code>.</li><li><strong>Moves</strong> <code>DATA_DIR/memory</code> and <code>DATA_DIR/agents</code> to <code>DATA_DIR/orgs/&lt;orgId&gt;/</code>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SAIDI_MIGRATE_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;at-least-10-chars&#39;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scripts/migrate-to-cloud.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> you@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Said&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --org-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Acme&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --seats</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dry-run</span></span></code></pre></div><p>The password comes from the environment so it never lands in shell history, and must be 10+ characters unless <code>--dry-run</code> is passed. The script always targets the <code>saidi_cloud</code> database regardless of the <code>SAIDI_CLOUD</code> flag in your shell. It is idempotent — an already-migrated deployment is detected and each step is skipped. Run it with <code>--dry-run</code> first, then without. Its own header says it plainly: back up the data directory and Mongo before running, because step 4 moves directories.</p><p>When it finishes, start the server with <code>SAIDI_CLOUD=1</code> and log in. Note that cloud mode requires <code>SAIDI_MASTER_KEY</code> for tenant secret encryption.</p><h2 id="safe-upgrade-procedure" tabindex="-1">Safe upgrade procedure <a class="header-anchor" href="#safe-upgrade-procedure" aria-label="Permalink to &quot;Safe upgrade procedure&quot;">​</a></h2><ol><li><p><strong>Read the changelog.</strong> Check <code>CHANGELOG.md</code> for the versions between yours and the target, and look for <code>BREAKING CHANGE</code> entries. Your running version is in the UI and in the root <code>package.json</code>.</p></li><li><p><strong>Take a backup.</strong> Both the database and <code>$SAIDI_HOME</code>, per the procedure above. Do not skip this even for a patch bump — migrations run automatically at boot and some of them move files.</p></li><li><p><strong>Stop the server</strong> with <code>SIGTERM</code> so the graceful shutdown drains debounced writes.</p></li><li><p><strong>Upgrade the code.</strong></p><p>From a source checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>From a published install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github:saeed9321/saidi-agent</span></span></code></pre></div><p>In Docker with <code>docker-compose.dist.yml</code>: bump the <code>SAIDI_REF</code> build arg to the new tag and run <code>docker compose up -d --build</code>. Do <strong>not</strong> use the in-app update dialog inside a container — it would install over the image layer and the change would vanish on the next recreate.</p></li><li><p><strong>Confirm <code>SAIDI_HOME</code> still points at the same directory.</strong> This is the most common way to &quot;lose&quot; data on upgrade: the resolution order is <code>SAIDI_HOME</code> → repo root (only with <code>SAIDI_DEV</code>) → <code>~/.saidi</code>, and a changed environment silently starts you on an empty install.</p></li><li><p><strong>Start the server and watch the boot log.</strong> A first boot after an upgrade may print <code>Migrated existing Saidi data (…) → &lt;DATA_DIR&gt;</code> or <code>Migrated SAIDI_HOME structured state to MongoDB (N runs, N chats, N activity rows)</code>. Both are expected once.</p></li><li><p><strong>Verify.</strong> Check that runs, memory, and agents are present in the UI, and that <code>/api/health</code> answers. From a source checkout you can also run <code>npm run typecheck</code> and <code>npm test</code>.</p></li><li><p><strong>If the new version misbehaves</strong>, stop it, reinstall the previous version, and restore the backup. Under the supervisor a post-update crash inside 60 seconds triggers an automatic rollback to the prior version; outside that window you roll back by hand.</p></li></ol><h3 id="rolling-back" tabindex="-1">Rolling back <a class="header-anchor" href="#rolling-back" aria-label="Permalink to &quot;Rolling back&quot;">​</a></h3><p>There is no down-migration. The forward migrations are additive to Mongo (import and backfill) with one exception: <code>scripts/migrate-to-cloud.mjs</code> moves <code>memory/</code> and <code>agents/</code> under <code>orgs/&lt;orgId&gt;/</code>. Rolling back across that point means restoring your pre-migration data directory and database from backup, not un-running the script.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/operations/deployment">Deployment &amp; Self-Hosting</a> — build pipeline, supervisor, environment</li><li><a href="/docs/reference/configuration">Configuration</a> — every setting and where it lives</li><li><a href="/docs/operations/troubleshooting">Troubleshooting</a> — boot failures and recovery</li></ul>`,52)])])}const u=t(i,[["render",d]]);export{g as __pageData,u as default};
